from save_review import save
from pathlib import Path
import json
articles={a['number']:a for a in json.loads((Path(__file__).resolve().parents[2]/'全书分段底稿.json').read_text())}
save(617,{2:'雷古勒斯是大远征期间派驻战帅荷鲁斯及第63远征舰队的机械教代表。',5:'荷鲁斯答应将从奥瑞提安技术联盟夺得的STC交给他，雷古勒斯受此诱惑，承诺让机械教为战帅效力。伊斯塔万三号战役前不久，荷鲁斯派他前往火星，协助说服铸造将军凯尔博·哈尔加入战帅阵营。后来，他又携带一种恶魔病毒返回火星，在“火星分裂”中支援哈尔的军队。',7:'雷古勒斯曾率荷鲁斯之子部队前去夺取“锻造库”，那是沃坎在大远征期间保管武器的秘库。他虽然找到了库址，却始终无法进入，直到用恶意废码感染铸造之父特’凯尔，迫使其从内部开启大门。钢铁之手铁父卡斯蒂甘·乌洛克此时赶到，击败了荷鲁斯之子。他一路追踪雷古勒斯至此，目标是找出控制众多复制分身的雷古勒斯“本体”。钢铁之手的战斗驳船进入星系后，雷古勒斯明白自己已无生路，便退回密室，准备清空数据核心。乌洛克原本打算活捉他、逼取情报，最后却直接将其杀死：截获的数据已经足够，既证实了沃坎造物的存在，也让他相信，自己可以用那些武器杀死荷鲁斯。'},notes={5:'本段 Aurelian Technocracy 与第616篇 Auretian Technocracy 为原稿异写，中文统一奥瑞提安技术联盟，保留英文待核。',7:'Wrought 是秘库专名，原译遗漏；暂译锻造库。prime 指控制分身的本体，不是重要程度上的“主要”。'},terms=[('Regulus','雷古勒斯'),('Wrought','锻造库'),("T'kell",'特’凯尔')])
save(618,{2:'西蒙·彭塔西安在荷鲁斯叛乱时期担任内政部之主。他性情阴沉，不苟言笑，却始终忠于帝国，竭力维系着庞大内政部的运转。',4:'叛乱期间，维索雷尔试图将机械教提升为正式的帝国机构，使其在泰拉议会获得正式席位，彭塔西安对此坚决反对。泰拉围城初期，他再次出席议会会议。此时他已开始借酒度日，罗格·多恩实施的戒严令又剥夺了他的大部分权力，但他仍然不分昼夜地履行职责。',6:'彭塔西安在叛乱中幸存，并成为重建大议会成员，在大清洗期间的动荡岁月里参与治理帝国。马卡多受选者的首领哈立德·哈桑曾游说他，主张确立泰拉高领主的权力，以制衡原体；叛乱已经让哈桑认识到原体可能带来的危险。哈桑还要求获得一个议会席位，却被彭塔西安斥为荒谬。此后，彭塔西安支持罗保特·基里曼夺回月球的计划，不过，他可能只是打算借机收回后勤与行政网络，恢复内政部的权势。',8:'彭塔西安认为马卡多受选者已失去存在价值，在与哈桑会面时，提出要接收他们的资产。然而，坐在面前的“哈桑”竟是一名卡利都司刺客；真正的哈桑此时已经成为新的刺客庭大导师。面对死亡或服从的选择，彭塔西安只得退让，承诺合作，并同意给予哈桑一个议会席位。'},notes={6:'“认为原体危险”“要求议会席位”的主语均为哈桑，原译指代混乱。',8:'原文 he 的指代略含混；结合替身揭露与职务语境，区分化身哈桑的刺客与取得刺客庭大导师职位的哈桑本人。'},terms=[('Simion Pentasian','西蒙·彭塔西安')])
q=next(b['text'] for b in articles[619]['blocks'] if b['id'].endswith('0001')).split('“荷鲁斯')[0].rstrip()
save(619,{
1:q+'\n\n“荷鲁斯唤起了亚空间那股最无情、最矛盾、也最不祥的力量中潜藏的黑暗狂怒。他召来了一个吞噬一切的摩洛的可怖神像，而他自己既是祭司，也是这一存在的化身。他此前分散四处、徒然耗散的力量，如今都汇聚起来，以骇人的威势指向同一个可怕的目标。”——摘自《变革时代：星语唱诗长尼莫·志明的查禁专论》',
3:'尼莫·志明在大远征与荷鲁斯叛乱期间担任星语庭的星语唱诗长。',
6:'尼莫是一位强大的灵能者，与灵能学院女导师安尼·萨拉希娜有恋情。他曾派雅典娜·迪约斯尝试修复星语者凯·祖兰受创的心智。登陆点大屠杀之后，红魔马格努斯以灵能强行突破帝国皇宫的防护，试图向帝皇传话，导致视界之城中的许多星语者陷入疯狂。尼莫遂派出隐感者首领埃万德·格雷戈拉斯，清除这些发疯的星语者。后来，他发现凯·祖兰掌握着足以影响叛乱走向的重要信息，又派长濑康追捕他。格雷戈拉斯自杀后，尼莫拿起他的最后一本日记，想弄清是什么促使他走上绝路。',
8:'泰拉围城前夕，尼莫·志明出席了泰拉议会会议。围城初期的另一次会议上，他指出荷鲁斯的许多盟友其实具有恶魔本质。围城最后阶段，他乘坐的穿梭机被击落，随后由胜宏及尤弗拉蒂·琪乐率领的一群幸存者找到。这群人正循着一道神秘光芒的指引，离开帝国圣所。',
10:'这群人后来与西吉斯蒙德及其圣殿骑士一同抵达空心山脉，却遭到泰弗斯率领的死亡守卫大举进攻，几乎必死无疑。战斗期间，尼莫与黑暗天使智库员密切协作，尝试重新点燃星炬，却未能成功。琪乐随后带领众多信徒作出牺牲性的祈祷，激起一场灵能反冲，不仅击退死亡守卫，还重新点亮了星炬。然而，这场祈祷也使许多信徒化为尘埃。',
12:'叛乱结束后，尼莫代表星语庭加入新成立的重建大议会，参与治理动荡中的帝国。此时他已成为热切的琪乐派信徒，并与西吉斯蒙德合作，将这位圣人藏匿起来。'
},notes={1:'conjured up 在此为召来、唤出，不是凭空幻想。Molech 的神像意象沿原文保留，不擅自解说为同名行星。',6:'英文把清剿安排在登陆点大屠杀之后，并与马格努斯的灵能闯入相联系；这是底稿时间线，不另凭背景记忆改动。',8:'recovered by 的行动者是胜宏等人；原文没有说他们击落了穿梭机。',10:'原文 but not to no avail 存在多余否定，与后文琪乐成功重启的转折相冲突；按上下文暂校为尝试未成，并保留疑点。'},terms=[('Nemo Zhi-Meng','尼莫·志明'),('Choirmaster','星语唱诗长'),('Aniq Sarashina','安尼·萨拉希娜'),('Athena Diyos','雅典娜·迪约斯'),('Evander Gregoras','埃万德·格雷戈拉斯'),('Cryptaesthesians','隐感者'),('City of Sight','视界之城'),('Keelerite','琪乐派信徒'),('The Age of Revolution: Suppressed Monographs of Choirmaster Nemo Zhi Meng','变革时代：星语唱诗长尼莫·志明的查禁专论')],title='尼莫·志明 Nemo Zhi-Meng')
save(620,{
2:'凯·祖兰是卡斯塔纳家族的一名星语者，荷鲁斯叛乱爆发之初在极限战士舰船阿尔戈号上服役。灵能者成为星语者时通常会失明，凯却装配了义眼，视力几乎与天生双眼无异；这在星语者中十分少见。',
5:'一连串异常猛烈的亚空间风暴击穿了阿尔戈号的盖勒力场，使舰船遭到重创。若非最后关头逃出亚空间，它便会彻底毁灭。船上只有凯·祖兰与罗克珊·卡斯塔纳幸存。',
7:'凯最初认为，阿尔戈号遭难是自己的责任。盖勒力场失效的瞬间，他正在传讯，因此怀疑是自己建立的灵能联系，让亚空间实体得以突破舰船防护。创伤与愧疚使他再也无法收发灵能讯息。卡斯塔纳家族的人员无法帮助他康复，只得将他送回泰拉的视界之城。',
9:'回到泰拉后，凯接受密集的恢复训练，希望重获原有的星语能力。红魔马格努斯为了警告父亲荷鲁斯即将背叛，强行闯入帝皇的网道工程，使训练骤然中断。随之而来的灵能爆发重创视界之城，杀死许多星语者。凯的导师在这一刻看见了某种未来幻象，并将其中揭示的秘密传入凯的脑海，藏进他的愧疚感深处，以防遭人察觉。',
11:'凯被带到空心山脉，准备接受强制的心智提取；秘密一旦被取出，他也将丧命。他一度抵住了侵入心智的力量，但迟早会被攻破。就在这时，几名“远征代表”的阿斯塔特越狱，顺势将他救出。这些战士所属的军团此时已知背叛了帝皇；率领他们的是千子战士阿塔瓦。他们逃亡时带上了凯，因为阿塔瓦知道他脑中藏有重要秘密，想将其掌握在手。',
13:'这些阿斯塔特自称“放逐亡者”，带着不情愿的凯穿越帝国皇宫附近的祈愿者之城。途中，吞世者阿舒巴发现，追兵正在利用凯的义眼追踪他们，便强行将义眼从他头上扯下，差点令其丧命。凯接受救治后才活了下来。',
15:'凯接连经历帝皇亲自与自己交谈的幻象，最终得以通过灵能将秘密传达给帝皇。当他终于接受阿尔戈号的灾难并非自己的过错后，天生的深紫色双眼竟自行再生；这也可能与他同帝皇的接触有关。',
17:'最终，凯在灾祸神殿自愿牺牲，防止任何人再从自己脑中取得那个秘密。他请罗克珊·卡斯塔纳揭开第三只眼，并直视其中，因此丧命。'
},notes={11:'所属军团背叛帝皇不等于这些被囚战士此刻人人已投混沌，译文保留主语层级。',15:'自责解除与接触帝皇都是英文提出的关联；眼睛再生的具体机制未被确证。'},terms=[('House Castana','卡斯塔纳家族'),('Argo','阿尔戈号'),('Roxanne Castana','罗克珊·卡斯塔纳'),('Atharva','阿塔瓦'),('Ashuba','阿舒巴'),('Temple of Woe','灾祸神殿')])
